PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS personal_difficulty(question_id TEXT PRIMARY KEY REFERENCES questions(id),rating TEXT NOT NULL CHECK(rating IN ('easy','medium','hard')),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS domains(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS skills(id INTEGER PRIMARY KEY,domain_id INTEGER NOT NULL REFERENCES domains(id),name TEXT NOT NULL,UNIQUE(domain_id,name));
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,skill_id INTEGER NOT NULL REFERENCES skills(id),difficulty TEXT NOT NULL CHECK(difficulty IN ('easy','medium','hard')),passage_html TEXT NOT NULL DEFAULT '',prompt_html TEXT NOT NULL,correct_answer TEXT NOT NULL CHECK(correct_answer IN ('A','B','C','D')),explanation_html TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS choices(question_id TEXT NOT NULL REFERENCES questions(id),letter TEXT NOT NULL CHECK(letter IN ('A','B','C','D')),content_html TEXT NOT NULL,PRIMARY KEY(question_id,letter));
CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY,question_id TEXT NOT NULL REFERENCES questions(id),file_path TEXT NOT NULL,media_type TEXT NOT NULL,alt_text TEXT,UNIQUE(question_id,file_path));
CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY,question_id TEXT NOT NULL REFERENCES questions(id),selected_answer TEXT NOT NULL,is_correct INTEGER NOT NULL CHECK(is_correct IN (0,1)),guessed INTEGER NOT NULL DEFAULT 0 CHECK(guessed IN (0,1)),answered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(question_id,selected_answer) REFERENCES choices(question_id,letter));
CREATE TABLE IF NOT EXISTS notes(question_id TEXT PRIMARY KEY REFERENCES questions(id),content TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS review_state(question_id TEXT PRIMARY KEY REFERENCES questions(id),needs_review INTEGER NOT NULL DEFAULT 0 CHECK(needs_review IN (0,1)),next_review_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tags(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS question_tags(question_id TEXT NOT NULL REFERENCES questions(id),tag_id INTEGER NOT NULL REFERENCES tags(id),PRIMARY KEY(question_id,tag_id));
CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY,filename TEXT NOT NULL,file_sha256 TEXT NOT NULL UNIQUE,imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS question_sources(question_id TEXT NOT NULL REFERENCES questions(id),source_id INTEGER NOT NULL REFERENCES sources(id),page_start INTEGER NOT NULL CHECK(page_start>=1),page_end INTEGER NOT NULL CHECK(page_end>=page_start),PRIMARY KEY(question_id,source_id,page_start));
CREATE INDEX IF NOT EXISTS idx_questions_filter ON questions(skill_id,difficulty);
CREATE INDEX IF NOT EXISTS idx_attempts_question_date ON attempts(question_id,answered_at,id);
CREATE INDEX IF NOT EXISTS idx_question_tags_tag ON question_tags(tag_id,question_id);
CREATE INDEX IF NOT EXISTS idx_review_due ON review_state(needs_review,next_review_at);
CREATE TABLE IF NOT EXISTS official_references(question_id TEXT PRIMARY KEY REFERENCES questions(id),official_id TEXT NOT NULL,external_id TEXT NOT NULL,match_method TEXT NOT NULL,recovered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
